\set ON_ERROR_STOP on
DO $$ BEGIN IF current_database()<>'wk_head_rh_permission_test' THEN RAISE EXCEPTION 'isolated fixture required';END IF;END $$;
ALTER TABLE ats_scorecards ADD COLUMN name text DEFAULT 'Fixture',ADD COLUMN description text,ADD COLUMN is_active boolean DEFAULT true,ADD COLUMN created_at timestamptz DEFAULT now(),ADD COLUMN updated_at timestamptz DEFAULT now();
ALTER TABLE ats_interview_kits ADD COLUMN owner_id uuid,ADD COLUMN name text DEFAULT 'Fixture',ADD COLUMN pipeline_id uuid,ADD COLUMN stage_value text,ADD COLUMN questions jsonb DEFAULT '[{"id":"q","text":"Fixture question","kind":"text"}]',ADD COLUMN is_default boolean DEFAULT false,ADD COLUMN created_at timestamptz DEFAULT now(),ADD COLUMN updated_at timestamptz DEFAULT now();
ALTER TABLE ats_interviewer_pools ADD COLUMN owner_id uuid,ADD COLUMN name text DEFAULT 'Fixture',ADD COLUMN description text,ADD COLUMN rotation_strategy text DEFAULT 'round_robin',ADD COLUMN rotation_cursor int DEFAULT 0,ADD COLUMN load_window_days int DEFAULT 14,ADD COLUMN created_at timestamptz DEFAULT now(),ADD COLUMN updated_at timestamptz DEFAULT now();
CREATE TABLE ats_interviewer_pool_members(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid,owner_id uuid,pool_id uuid REFERENCES ats_interviewer_pools(id) ON DELETE CASCADE,interviewer_id uuid,weight int DEFAULT 1,created_at timestamptz DEFAULT now());
CREATE TABLE ats_interviewer_availability(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid,owner_id uuid,interviewer_id uuid,weekday int,start_minute int,end_minute int,timezone text DEFAULT 'America/Sao_Paulo',created_at timestamptz DEFAULT now());
ALTER TABLE ats_scorecards ENABLE ROW LEVEL SECURITY;ALTER TABLE ats_interview_kits ENABLE ROW LEVEL SECURITY;ALTER TABLE ats_interviewer_pools ENABLE ROW LEVEL SECURITY;ALTER TABLE ats_interviewer_pool_members ENABLE ROW LEVEL SECURITY;ALTER TABLE ats_interviewer_availability ENABLE ROW LEVEL SECURITY;
GRANT SELECT,INSERT,UPDATE,DELETE ON ats_scorecards,ats_interview_kits,ats_interviewer_pools,ats_interviewer_pool_members,ats_interviewer_availability TO authenticated,service_role;
INSERT INTO permissions(key,module,resource,action,scope,label_pt)
SELECT 'techhire.'||r||'.'||a||'.'||s,'techhire',r,a::public.perm_action,s::public.perm_scope,'Fixture' FROM unnest(ARRAY['scorecards','interview_kits'])r CROSS JOIN unnest(ARRAY['view','create','update','delete'])a CROSS JOIN unnest(ARRAY['own','team','workspace'])s ON CONFLICT DO NOTHING;
INSERT INTO job_role_permission_overrides(workspace_id,role_id,permission_key,effect,created_by) SELECT '184b9435-0a9b-4334-9e89-8854dc883f5d','aaaaaaaa-0000-4000-8000-000000000004',key,'grant','1c237fbe-079e-4eb9-a3e6-c08d85e79688' FROM permissions WHERE resource IN('scorecards','interview_kits') ON CONFLICT DO NOTHING;
